SELECT set_config('aka.v347_before',(SELECT to_jsonb(s)::text FROM (WITH meta AS (SELECT jsonb_build_object(
 'columns',(SELECT jsonb_agg(jsonb_build_object('name',a.attname,'position',a.attnum,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'identity',a.attidentity,'generated',a.attgenerated,'comment',col_description(a.attrelid,a.attnum)) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid='public.auto_campaign_action_detail_statuses'::regclass AND a.attnum>0 AND NOT a.attisdropped),
 'constraints',(SELECT jsonb_agg(jsonb_build_object('name',conname,'definition',pg_get_constraintdef(oid)) ORDER BY conname) FROM pg_constraint WHERE conrelid='public.auto_campaign_action_detail_statuses'::regclass),
 'incoming_foreign_keys',(SELECT jsonb_agg(jsonb_build_object('table',conrelid::regclass::text,'name',conname,'definition',pg_get_constraintdef(oid)) ORDER BY conname) FROM pg_constraint WHERE confrelid='public.auto_campaign_action_detail_statuses'::regclass),
 'indexes',(SELECT jsonb_agg(jsonb_build_object('name',indexname,'definition',indexdef) ORDER BY indexname) FROM pg_indexes WHERE schemaname='public' AND tablename='auto_campaign_action_detail_statuses'),
 'triggers',(SELECT jsonb_agg(jsonb_build_object('name',tgname,'definition',pg_get_triggerdef(oid)) ORDER BY tgname) FROM pg_trigger WHERE tgrelid='public.auto_campaign_action_detail_statuses'::regclass AND NOT tgisinternal),
 'policies',(SELECT jsonb_agg(to_jsonb(p) ORDER BY policyname) FROM pg_policies p WHERE schemaname='public' AND tablename='auto_campaign_action_detail_statuses'),
 'access',(SELECT jsonb_build_object('owner',pg_get_userbyid(relowner),'acl',relacl,'rls',relrowsecurity,'force_rls',relforcerowsecurity) FROM pg_class WHERE oid='public.auto_campaign_action_detail_statuses'::regclass),
 'sequence_definition',(SELECT to_jsonb(s)-'last_value' FROM pg_sequences s WHERE schemaname='public' AND sequencename='auto_campaign_action_detail_statuses_id_seq')) AS data)
SELECT 'cgjbsmqtfhqvttudyjzq' AS project_ref,clock_timestamp() AS captured_at,
 (SELECT count(*) FROM public.auto_campaign_action_detail_statuses) AS row_count,
 (SELECT md5(coalesce(string_agg(to_jsonb(t)::text,'|' ORDER BY id),'')) FROM public.auto_campaign_action_detail_statuses t) AS table_md5,
 (SELECT jsonb_agg(jsonb_build_object('row',to_jsonb(t),'canonical',to_jsonb(t)::text,'md5',md5(to_jsonb(t)::text)) ORDER BY id) FROM public.auto_campaign_action_detail_statuses t) AS rows,
 meta.data AS schema,meta.data::text AS schema_canonical,md5(meta.data::text) AS schema_md5,
 (SELECT jsonb_build_object('last_value',last_value,'is_called',is_called) FROM public.auto_campaign_action_detail_statuses_id_seq) AS sequence_state,
 (SELECT jsonb_object_agg(p.oid::regprocedure::text,md5(pg_get_functiondef(p.oid)) ORDER BY p.oid::regprocedure::text) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.prokind='f' AND (strpos(p.prosrc,'auto_campaign_action_detail_statuses')>0 OR p.proname IN ('aka_agent_apply_voice_call_event','aka_agent_commit_voice_call_dial','aka_agent_record_sms_message_status'))) AS runtime_checksums,(SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY id),'[]'::jsonb) FROM public.auto_automation_trigger_statuses r) AS automation_conditions,
 (SELECT md5(string_agg(to_jsonb(e)::text,'|' ORDER BY id)) FROM public.auto_error e) AS auto_error_md5
FROM meta) s),true);
ALTER TABLE public.auto_campaign_action_detail_statuses ADD COLUMN description text NOT NULL DEFAULT 'Danh mục trạng thái chi tiết chiến dịch, không phải policy lỗi hay lịch sử một lần chạy. Đọc campaign_action_id để biết loại chiến dịch; action_code NULL nghĩa là mọi hành động trong loại đó, có giá trị nghĩa là chỉ hành động đó. status_value được so khớp không phân biệt hoa/thường; label chỉ để hiển thị. status_id NULL nghĩa là chưa gắn nhóm ngữ nghĩa auto_status, không phải dữ liệu hỏng. Không suy ra thành công, retry, khóa tài khoản hoặc kết quả gửi/nhận từ việc có dòng danh mục; đối chiếu detail/log và runtime. Dòng có thể được seed, lưu từ Automation hoặc tự sinh khi runtime ghi detail. Mô tả chỉ phục vụ agent, không tham gia điều kiện chạy.';
COMMENT ON COLUMN public.auto_campaign_action_detail_statuses.description IS 'Agent-readable documentation only. Not executed or used for Automation matching. New auto-generated rows inherit a generic explanation; curated rows have contextual descriptions. NULL action_code is a wildcard, NULL status_id means no semantic group.';
